import argparse
import json
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote


class Store:
    def __init__(self):
        self.lock = threading.Lock()
        self.data = {}  # key -> (value, expires_at or None)

    def _live(self, key, now):
        item = self.data.get(key)
        if item is None:
            return None
        if item[1] is not None and item[1] <= now:
            del self.data[key]
            return None
        return item

    def put(self, key, value, ttl):
        with self.lock:
            now = time.monotonic()
            existed = self._live(key, now) is not None
            self.data[key] = (value, None if ttl is None else now + ttl)
            return existed

    def get(self, key):
        with self.lock:
            item = self._live(key, time.monotonic())
            return item

    def delete(self, key):
        with self.lock:
            if self._live(key, time.monotonic()) is None:
                return False
            del self.data[key]
            return True

    def keys(self):
        with self.lock:
            now = time.monotonic()
            return sorted(k for k in list(self.data) if self._live(k, now) is not None)


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *args):
        pass

    def _send(self, status, obj=None):
        body = b"" if obj is None else json.dumps(obj).encode()
        self.send_response(status)
        if obj is not None:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def _key(self):
        """Return key, or None if the path is not /kv/<key>."""
        path = self.path.split("?", 1)[0].split("#", 1)[0]
        if not path.startswith("/kv/"):
            return None
        raw = path[4:]
        if not raw or "/" in raw:
            return None
        return unquote(raw)

    def _is_list(self):
        return self.path.split("?", 1)[0] in ("/kv",)

    def _drain(self):
        n = int(self.headers.get("Content-Length") or 0)
        return self.rfile.read(n) if n > 0 else b""

    def do_GET(self):
        self._drain()
        if self._is_list():
            return self._send(200, {"keys": self.server.store.keys()})
        key = self._key()
        if key is None:
            return self._send(404, {"error": "not found"})
        item = self.server.store.get(key)
        if item is None:
            return self._send(404, {"error": "not found"})
        self._send(200, {"key": key, "value": item[0]})

    def do_DELETE(self):
        self._drain()
        key = self._key()
        if key is None:
            return self._send(404, {"error": "not found"})
        if self.server.store.delete(key):
            return self._send(204)
        self._send(404, {"error": "not found"})

    def do_PUT(self):
        raw = self._drain()
        key = self._key()
        if key is None:
            return self._send(404, {"error": "not found"})
        try:
            body = json.loads(raw.decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            return self._send(400, {"error": "invalid JSON"})
        if not isinstance(body, dict):
            return self._send(400, {"error": "body must be a JSON object"})
        if "value" not in body:
            return self._send(400, {"error": "missing value"})
        ttl = body.get("ttl")
        if "ttl" in body:
            if (isinstance(ttl, bool) or not isinstance(ttl, (int, float))
                    or not ttl > 0 or ttl == float("inf")):
                return self._send(400, {"error": "ttl must be a number greater than 0"})
        else:
            ttl = None
        existed = self.server.store.put(key, body["value"], ttl)
        self._send(200 if existed else 201, {"key": key, "value": body["value"]})

    def do_POST(self):
        self._drain()
        self._send(405, {"error": "method not allowed"})

    do_PATCH = do_POST
    do_HEAD = do_POST
    do_OPTIONS = do_POST


def make_server(host, port):
    server = ThreadingHTTPServer((host, port), Handler)
    server.daemon_threads = True
    server.store = Store()
    return server


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--port", type=int, required=True)
    p.add_argument("--host", default="127.0.0.1")
    args = p.parse_args()
    make_server(args.host, args.port).serve_forever()


if __name__ == "__main__":
    main()

