                return self._send(404, {"error": "not found"})
            del self.server.store[k]
        self._send(204)

    def do_PUT(self):
        kind, k = self._route()
        raw = self._body()
        if kind is None:
            return self._send(404, {"error": "not found"})
        if kind == "list":
            return self._send(405, {"error": "method not allowed"})
